public static <V> void reverse(V[] arr, int from, int to) {
    // Check if the array is null or empty
    if (arr == null || arr.length == 0) {
        return;
    }

    // Check if the indices are within the bounds of the array
    if (from < 0 || to >= arr.length) {
        return;
    }

    // Reverse the elements in the range [from, to]
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

