private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // initialize the circulator to the start node
    OuterFaceCirculator circ = new OuterFaceCirculator(start);
    // traverse the component in the given direction until we find a node that satisfies the predicate or reach the stop node
    while (!circ.getCurrent().equals(stop)) {
        if (predicate.test(circ.getCurrent())) {
            // if the current node satisfies the predicate, return the circulator to it
            return circ;
        } else {
            // otherwise, move on to the next node in the direction of the traversal
            circ.move(dir);
