private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer,Integer>>,E>> separators = new ArrayList<>();
    for (E edge : graph.edgeSet()) {
        Set<Integer> neighbors = new HashSet<>();
        for (V vertex : graph.neighborListOf(edge)) {
            neighbors.add(vertex);
        }
        for (V vertex : graph.neighborListOf(edge)) {
            Set<Integer> neighborSeparators = new HashSet<>();
            for (E neighborEdge : graph.getEdgeIterable(vertex)) {
                if (neighborEdge.equals(edge)) {
                    continue;
                }
                for (V neighborVertex : graph.neighborListOf(neighborEdge)) {
                    if (!neighborVertex.equals(vertex)) {
                        neighborSeparators.add(neighborVertex);
                    }
                }
            }
            separators.add(Pair.of(neighborSeparators, edge));
        }
    }
