public static String applyRelativePath(String path, String relativePath) {
    // Validate input
    if (path == null || path.isEmpty()) {
        throw new IllegalArgumentException("Path cannot be null or empty.");
    }
    if (relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Relative path cannot be null or empty.");
    }
    // Normalize input
    String normalizedPath = path.replace('\\', '/');
    String normalizedRelativePath = relativePath.replace('\\', '/');

    // Split and join paths
    List<String> pathParts = Arrays.asList(normalizedPath.split("/"));
    List<String> relativePathParts = Arrays.asList(normalizedRelativePath.split("/"));
    List<String> joinedPathParts = new ArrayList<>();
    for (int i = 0; i < pathParts.size(); i++) {
        String currentPathPart = pathParts.get(i);
        if (currentPathPart.equals(".")) {
            continue;
        } else if (currentPathPart.equals("..")) {
            joinedPathParts.add(relativePathParts.get(i - 1));
        } else {
            joinedPathParts.add(currentPathPart);
        }
    }
    return String.join("/", joinedPathParts);
}

