    String yearString = tbString.substring(0, 4);
    String monthString = tbString.substring(4, 6);
    String dayString = tbString.substring(6, 8);
    int day = Integer.parseInt(dayString);
    int month = Integer.parseInt(monthString);
    int year = Integer.parseInt(yearString);
    int daysInMonth = getDaysInMonth(year, month);
    if (dayStep > daysInMonth) {
      throw new IllegalArgumentException("Day step cannot be greater than the number of days in the month");
    }
    day = (int) Math.floor((double) day / dayStep) * dayStep;
    dayString = String.format("%02d", day);
    tbString = yearString + monthString + dayString;
    return Long.parseLong(tbString);
  }

public static long compressTimeBucket(long timeBucket, int dayStep) {
    return timeBucket - (timeBucket - 1) % dayStep;
