public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket < 0 || dayStep < 1) {
        throw new IllegalArgumentException("Invalid time bucket or day step: " + timeBucket + ", " + dayStep);
    }

    if (dayStep == 1) {
        return timeBucket;
    }

    long datePart = timeBucket % 10000;
    long timePart = timeBucket % 100;
    int dayPart = (int) (timeBucket / 10000);

    int newDayPart = dayPart - (dayPart % dayStep);
    int newMonthPart = (int) (timePart / 10000);

    if (newMonthPart == 0) {
        newMonthPart = 12;
    }

    return newDayPart * 10000 + newMonthPart * 100 + timePart;
}

