public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Check if the file is null
    if (file == null) {
        throw new IllegalArgumentException("The file cannot be null");
    }

    // Check if the time ranges are null or empty
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("The time ranges cannot be null or empty");
    }

    // Check if the time ranges are valid
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if (timeRange.getStartTime() > timeRange.getEndTime()) {
            throw new IllegalArgumentException("The start time must be earlier than the end time");
        }
    }

    // Parse the file using the time ranges
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        long startTime = timeRange.getStartTime();
        long endTime = timeRange.getEndTime();

        // Read the file and extract the thread snapshots
        List<String> threadSnapshotLines = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.startsWith("THREAD SNAPSHOT")) {
                    threadSnapshotLines.add(line);
                }
            }
        } catch (IOException e) {
            throw new RuntimeException("Failed to read the file", e);
        }

        // Parse the thread snapshots
        for (String threadSnapshotLine : threadSnapshotLines) {
            ThreadSnapshot threadSnapshot = new ThreadSnapshot();
            String[] tokens = threadSnapshotLine.split("\\s+");
            threadSnapshot.setName(tokens[0]);
            threadSnapshot.setId(Integer.parseInt(tokens[1]));
            threadSnapshot.setState(Thread.State.valueOf(tokens[2]));
            threadSnapshot.setStartTime(Long.parseLong(tokens[3]));
            threadSnapshot.setEndTime(Long.parseLong(tokens[4]));
            threadSnapshot.setCpuTime(Long.parseLong(tokens[5]));
            threadSnapshot.setUserTime(Long.parseLong(tokens[6]));
            threadSnapshot.setBlockedTime(Long.parseLong(tokens[7]));
            threadSnapshot.setWaitedTime(Long.parseLong(tokens[8]));
            threadSnapshot.setStackTrace(Arrays.asList(tokens).subList(9, tokens.length));
            threadSnapshots.add(threadSnapshot);
        }
    }

    return threadSnapshots;
}

