    BufferedReader reader = new BufferedReader(new FileReader(file));
    String line;
    while ((line = reader.readLine()) != null) {
        //Split the line into columns
        String[] columns = line.split("\t");

        //Get the time range of the current thread snapshot
        long threadSnapshotTimeStart = Long.parseLong(columns[threadSnapshotsIndex + 1]);
        long threadSnapshotTimeEnd = Long.parseLong(columns[threadSnapshotsIndex + 2]);

        //Check if the thread snapshot's time range is within the specified time ranges
        boolean isInTimeRange = false;
        for (int i = 0; i < timeRanges.size(); i++) {
            ProfileAncodeInvestimeRange timeRange = timeRanges.get(i);
            if (threadSnapshotTimeStart >= timeRange.start && threadSnapshotTimeEnd <= timeRange.end) {
                isInTimeRange = true;
                break;
            }
        }

        if (isInTimeRange) {
            //Extract the thread snapshot's ID and state
